<template>
 <div class="dashboard">
  <div class="dashboard-heading"><div><span class="page-kicker">YOUR COMMUNITY AT A GLANCE</span><h1 class="page-title">A good day starts at home<span class="title-dot">.</span></h1><p class="lead">Your Emerald community, within your permitted access.</p></div><button class="button button-secondary refresh-button" :disabled="loading" @click="load"><Icon name="refresh" :class="{spinning:loading}" :size="16"/>{{ loading?'Refreshing':'Refresh' }}</button></div>
  <p class="sr-only" role="status" aria-atomic="true">{{ loading?'Refreshing overview...':refreshedAt?'Overview updated.':'' }}</p><StatusMessage :message="error" error retry @retry="load"/>
  <div class="stats-grid" :aria-busy="loading">
   <router-link v-if="canRead('MEMBER_VIEW')" to="/members" class="stat-card"><span class="stat-icon plum"><Icon name="people" :size="23"/></span><span class="stat-label">{{ can('MEMBER_VIEW')?'Community members':'My registered record' }}</span><strong>{{ memberTotal===null?'—':memberTotal }}</strong><span class="stat-foot">People in your permitted directory<Icon name="arrow" :size="15"/></span></router-link>
   <router-link v-if="canRead('FLAT_VIEW')" to="/flats" class="stat-card"><span class="stat-icon peach"><Icon name="building" :size="23"/></span><span class="stat-label">{{ can('FLAT_VIEW')?'Registered flats':'My permitted flats' }}</span><strong>{{ flatTotal===null?'—':flatTotal }}</strong><span class="stat-foot">Homes in your permitted directory<Icon name="arrow" :size="15"/></span></router-link>
   <a v-if="can('SOCIETY_VIEW')" href="#floor-explorer" class="stat-card"><span class="stat-icon lavender"><Icon name="layers" :size="23"/></span><span class="stat-label">Society floors</span><strong>{{ loading&&!$store.state.floors.length?'—':$store.state.floors.length }}</strong><span class="stat-foot">Explore your building<Icon name="arrow" :size="15"/></span></a>
  </div>
  <section class="welcome-banner"><div class="welcome-copy"><span class="eyebrow">A LITTLE MORE CONNECTED</span><h2>People make a place.<br/><em>You make it a community.</em></h2><p>Keep the everyday running smoothly, so there's more room for the moments that matter.</p></div><div class="hero-illustration" aria-hidden="true"><div class="hero-orbit"></div><div class="mini-building"><span v-for="n in 12" :key="n"></span></div><div class="floating-label"><span class="tiny-dot"></span>Better together</div><div class="hero-home"><Icon name="home" :size="47"/></div></div></section>
  <div class="dashboard-columns">
   <section v-if="can('SOCIETY_VIEW')" class="society-section" id="floor-explorer"><div class="section-heading"><div><span class="page-kicker">GET TO KNOW YOUR SPACE</span><h2 class="section-title">Explore your building</h2></div><span class="subtle-tag">{{ $store.state.floors.length }} floors</span></div>
    <div v-if="$store.state.society" class="society-detail"><span class="society-avatar"><Icon name="building" :size="25"/></span><div><strong>{{ $store.state.society.societyName }}</strong><span class="muted">Choose a floor to see permitted flats</span></div></div>
    <div class="floor-list"><button v-for="floor in pagedFloors" :key="floor.floorNumber" :disabled="!canRead('FLAT_VIEW')" :class="{selected:selectedFloor===floor.floorNumber}" :aria-pressed="selectedFloor===floor.floorNumber" @click="selectFloor(floor.floorNumber)"><span>FLOOR</span>{{ String(floor.floorNumber).padStart(2,'0') }}</button></div>
    <Pagination :page="floorPage" :pages="floorPages" label="Floors pagination" @change="floorPage=$event"/>
    <div v-if="selectedFloor!==null" class="floor-results" aria-live="polite"><div class="section-heading"><strong>Floor {{ selectedFloor }}</strong><router-link to="/flats">View directory<Icon name="arrow" :size="14"/></router-link></div><p v-if="floorLoading" class="body-text">Finding flats...</p><StatusMessage v-else-if="floorError" :message="floorError" error retry @retry="selectFloor(selectedFloor)"/><div v-else-if="floorFlats.length" class="flat-chips"><router-link v-for="flat in pagedFloorFlats" :key="flat.flatId" :to="'/flats/'+flat.flatId"><Icon name="home" :size="16"/>{{ flat.flatNumber }}</router-link></div><p v-else class="body-text">No permitted flats on this floor.</p><Pagination :page="flatPage" :pages="flatPages" :disabled="floorLoading" label="Floor flats pagination" @change="flatPage=$event"/></div>
   </section>
   <section class="quick-actions-panel"><span class="page-kicker">MAKE YOURSELF AT HOME</span><h2 class="section-title">Everyday essentials</h2>
    <router-link v-if="can('MEMBER_CREATE')" to="/members/new" class="quick-action"><Icon name="people"/><span><strong>Add a member</strong><small>Register a person in the community</small></span><Icon name="chevron" :size="16"/></router-link>
    <router-link v-if="can('FLAT_CREATE')" to="/flats/new" class="quick-action"><Icon name="building"/><span><strong>Register a flat</strong><small>Make room for another home</small></span><Icon name="chevron" :size="16"/></router-link>
    <router-link v-if="canRead('FAMILY_VIEW')" to="/family" class="quick-action"><Icon name="people"/><span><strong>Family details</strong><small>Your permitted family records</small></span><Icon name="chevron" :size="16"/></router-link>
    <router-link v-if="canRead('MEMBER_VIEW')" to="/owners" class="quick-action"><Icon name="home"/><span><strong>Owners & flats</strong><small>Registered ownership and history</small></span><Icon name="chevron" :size="16"/></router-link>
    <div class="community-note"><Icon name="home" :size="24"/><p>Good communities grow<br/><strong>one connection at a time.</strong></p></div><p v-if="refreshedAt" class="last-refreshed"><Icon name="clock" :size="13"/>Updated {{ refreshedAt }}</p>
   </section>
  </div>
 </div>
</template>
<script>
import access from '../util/access-mixin';import Pagination from '../components/Pagination.vue';import {pageItems,pageCount} from '../util/pagination.cjs';import Icon from '../components/Icon.vue';import StatusMessage from '../components/StatusMessage.vue';import {api,errorMessage} from '../services/api';
export default {
 mixins:[access],components:{Icon,StatusMessage,Pagination},data:()=>({loading:false,error:'',memberTotal:null,flatTotal:null,refreshedAt:'',selectedFloor:null,floorFlats:[],floorLoading:false,floorError:'',floorRequest:0,floorPage:0,flatPage:0}),
 computed:{floorPages(){return pageCount(this.$store.state.floors.length);},pagedFloors(){return pageItems(this.$store.getters.sortedFloors,this.floorPage);},flatPages(){return pageCount(this.floorFlats.length);},pagedFloorFlats(){return pageItems(this.floorFlats,this.flatPage);}},
 created(){this.load();},beforeUnmount(){if(this.floorController)this.floorController.abort();this.floorRequest++;},
 methods:{
  async load(){this.loading=true;this.error='';try{const [,members,flats]=await Promise.all([this.can('SOCIETY_VIEW')?this.$store.dispatch('loadReferenceData'):Promise.resolve(),this.canRead('MEMBER_VIEW')?api.page('members'):Promise.resolve(null),this.canRead('FLAT_VIEW')?api.page('flats'):Promise.resolve(null)]);this.memberTotal=members?members.totalElements:null;this.flatTotal=flats?flats.totalElements:null;this.refreshedAt=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});if(this.selectedFloor!==null)await this.selectFloor(this.selectedFloor);}catch(e){this.error=errorMessage(e);}finally{this.loading=false;}},
  async selectFloor(number){if(this.floorController)this.floorController.abort();this.floorController=new AbortController();const request=++this.floorRequest;this.flatPage=0;this.selectedFloor=number;this.floorLoading=true;this.floorError='';this.floorFlats=[];try{const data=await api.flatsByFloor(number,{signal:this.floorController.signal});if(request===this.floorRequest)this.floorFlats=data;}catch(e){if(e.code!=='ERR_CANCELED'&&request===this.floorRequest)this.floorError=errorMessage(e);}finally{if(request===this.floorRequest)this.floorLoading=false;}}
 }
};
</script>
